"use client";

import { useEffect, useState } from "react";

import { trpc } from "./_trpc/client";

/**
 * Root page that calls the streaming `streamWords` procedure and
 * displays the words as they arrive, joined with a space.
 */
export default function Home() {
  const [words, setWords] = useState<string[]>([]);

  // `useQuery` subscribes to the streamed procedure. As the server
  // yields values, `query.data` is updated with the latest value.
  const query = trpc.chat.streamWords.useQuery(undefined, {
    // Streamed procedures can take a while; keep refetching simple.
    staleTime: Infinity,
  });

  // Accumulate every yielded word so the final text is the
  // concatenation of all streamed chunks, separated by spaces.
  useEffect(() => {
    if (typeof query.data === "string") {
      setWords((prev) =>
        prev.includes(query.data as string) ? prev : [...prev, query.data as string],
      );
    }
  }, [query.data]);

  return (
    <main style={{ padding: "2rem", fontFamily: "system-ui, sans-serif" }}>
      <h1>tRPC v11 Streaming Demo</h1>
      <div
        id="chat-output"
        data-testid="chat-output"
        style={{
          marginTop: "1rem",
          padding: "1rem",
          border: "1px solid #ccc",
          borderRadius: "8px",
          minHeight: "2rem",
          fontSize: "1.25rem",
        }}
      >
        {words.join(" ")}
      </div>
    </main>
  );
}

